import json
d=json.load(open('measurements.json'))
def show(x,depth=0,key='root'):
    pad='  '*depth
    if isinstance(x,dict):
        print(pad+str(key)+': dict keys=',list(x.keys()))
        for k,v in x.items(): show(v,depth+1,k)
