from load import *
import numpy as np
for p in 'abcd':
    V,G=sts(p)
    # background estimate: linear in |V| fit from regions outside band
    print('panel',p)
    # print fraction of weight below 0 with a few background models
    for bgmode in ['none','lin']:
        if bgmode=='none': Gb=G.copy()
        else:
            # fit bg = a*|V| using |V|>9 region
            m=np.abs(V)>9
            a=np.sum(G[m]*np.abs(V[m]))/np.sum(np.abs(V[m])**2)
            Gb=G-a*np.abs(V)
        # define band region: where smoothed G > 0.2 roughly + inner region
        k=9; Gs=np.convolve(G,np.ones(k)/k,mode='same')
        inband = Gs>0.18
        idx=np.where(inband)[0]
        lo,hi=V[idx[0]],V[idx[-1]]
        sel=(V>=lo-0.1)&(V<=hi+0.1)
        neg=np.trapz(np.clip(Gb[sel&(V<0)],0,None),V[sel&(V<0)])
        pos=np.trapz(np.clip(Gb[sel&(V>0)],0,None),V[sel&(V>0)])
        print('  bg',bgmode,'band range',round(lo,2),round(hi,2),'neg',round(neg,3),'pos',round(pos,3),'frac below',round(neg/(neg+pos),3))
"

